type Org = {
  id: string;
  name: string;
};

type User = {
  id: string;
  orgId: string;
  org?: Org;
};

async function loadUser(id: string): Promise<User> {
  const userResponse = await fetch(`/api/users/${id}`);
  if (!userResponse.ok) {
    throw new Error(`bad status ${userResponse.status}`);
  }

  const user = (await userResponse.json()) as User;

  const orgResponse = await fetch(`/api/orgs/${user.orgId}`);
  if (!orgResponse.ok) {
    throw new Error(`bad status ${orgResponse.status}`);
  }

  const org = (await orgResponse.json()) as Org;
  user.org = org;

  return user;
}

async function loadUsers(ids: string[]): Promise<User[]> {
  return Promise.all(ids.map((id) => loadUser(id)));
}

export { loadUser, loadUsers };

